def t(label)
  r = yield
  puts "#{label}\t#{r.inspect}"
rescue Exception => e
  # A NameError for a UTF-16LE method name cannot even spell its
  # message (CRuby raises CompatibilityError building it).
  msg = (e.message rescue "(no message: #{$!.class})")
  puts "#{label}\t#{e.class}: #{msg.lines.first.to_s.chomp}"
end
